def avg_unemployment_ratio(df_district):
    df_1995 = df_district[(df_district['A4'] == 'yes') & (df_district['A1'].str.contains('1995'))]
    df_1996 = df_district[(df_district['A4'] == 'yes') & (df_district['A1'].str.contains('1996'))]

    avg_1995 = df_1995['A3'].mean()
    avg_1996 = df_1996['A3'].mean()

    if avg_1995 > avg_1996:
        return '1995'
    elif avg_1995 < avg_1996:
        return '1996'
    else:
        return 'Equal'
```

