import pandas as pd

def compute_feature(account, card, client, disp, district, loan, order, trans):
    # Merge tables to find transactions related to household payments in Pisek
    merged = account.merge(
        card, left_on='account_id', right_on='card_id'
    ).merge(
        disp, on='disp_id'
    ).merge(
        client, on='client_id'
    ).merge(
        district, on='district_id'
    ).merge(
        order, on='account_id'
    ).merge(
        trans, on='account_id'
    )

    # Filter for household payment and specific district (Pisek)
    filtered = merged[
        (merged['k_symbol'] == 'POJISTENI') &
        (merged['A2'] == 'Pisek')
    ]

    # Extract unique account IDs
    result = filtered[['account_id']].drop_duplicates()

    return result
```

