import pandas as pd

def get_transactions_from_district_5(account, trans):
    return (
        account
        .merge(trans, how="inner", left_on="account_id", right_on="account_id")
        .query("district_id == 5")
        [["trans_id", "date", "type", "operation", "amount", "balance"]]
    )
```

